#include <iostream>
#include <string>

void showStats(const std::string& label, const std::string& str) {
    std::cout << label << ":\n"
              << "  size: " << str.size()
              << ", length: " << str.length()
              << ", empty: " << std::boolalpha << str.empty()
              << ", capacity >= size: " << (str.capacity() >= str.size())
              << '\n';
}

int main() {
    std::string s;
    showStats("1. Empty string", s);

    s = "tomato";
    showStats("2. After assigning 'tomato'", s);

    s += "1234567890abcdefghijklmnopqrstuvwxyz1234567890";
    showStats("3. After appending 46 chars", s);

    s.resize(s.size() + 10, '*');
    showStats("4. After resize(+10, '*')", s);
    std::cout << "  Suffix: " << s.substr(s.size() - 10) << "\n\n";

    std::string first = "one";
    std::string second = "two";
    std::cout << "Before swap: first=" << first << ", second=" << second << '\n';
    first.swap(second);
    std::cout << "After swap:  first=" << first << ", second=" << second << '\n';

    return 0;
}

#include <iostream>
#include <string>

int main() {
    const std::string text = "noon is 12 pm; midnight is not.";
    std::cout << "String: " << text << "\n\n";

    // 1. Exact substring matching with find and rfind
    std::cout << "find(\"is\"): " << text.find("is") << '\n';
    std::cout << "rfind(\"is\"): " << text.rfind("is") << '\n';

    // 2. Character set searching with find_first_of and find_last_of
    std::string vowels = "misop";
    auto first_match = text.find_first_of(vowels);
    auto last_match = text.find_last_of(vowels);
    std::cout << "find_first_of(\"misop\"): '" << text[first_match] << "' at " << first_match << '\n';
    std::cout << "find_last_of(\"misop\"): '" << text[last_match] << "' at " << last_match << '\n';

    // 3. Negated set searching with find_first_not_of
    auto not_letters = text.find_first_not_of("noi spm");
    std::cout << "find_first_not_of(\"noi spm\"): '" << text[not_letters] << "' at " << not_letters << '\n';

    // Search failure returning npos
    auto failed = text.find_first_not_of("noon is 12 pm; midnight is not.");
    if (failed == std::string::npos) {
        std::cout << "Searching for missing char returned string::npos\n";
    }

    return 0;
}
